 const labels=M.map((m,i)=>{const t=(i-2.5)*40*Math.PI/180;return `<text x="${(110+64*Math.sin(t)).toFixed(1)}" y="${(138-64*Math.cos(t)+4).toFixed(1)}" font-size="11" fill="${m==mode?'#fff':'#2a2417'}" text-anchor="middle" font-family="Arial" font-weight="700">${L[i]}</text>`}).join('');
